mapper.select:
SELECT id
FROM chat_rooms
WHERE user_low_id = #{userLowId}
  AND user_high_id = #{userHighId}

SELECT COUNT(*) > 0
FROM chat_room_participants
WHERE room_id = #{roomId}
  AND user_id = #{userId}

SELECT user_id
FROM chat_room_participants
WHERE room_id = #{roomId}

mapper.update:
UPDATE chat_rooms
SET updated_at = NOW()
WHERE id = #{roomId}

UPDATE chat_room_participants
SET last_read_at = #{lastReadAt}
WHERE room_id = #{roomId}
  AND user_id = #{userId}
